 1 │ /**
 2 │  * How an inference endpoint URL is identified and persisted.
 3 │  *
 4 │  * Records (task, session, provider recovery) keep the origin and path only: userinfo, query string and fragment can
 5 │  * carry credentials (`REDACTED and are never written. Comparison uses the same form,
 6 │  * with scheme and host lower-cased and trailing slashes dropped.
 7 │  */
 8 │ 
 9 │ function parse(endpoint: string): URL | undefined {
10 │   try {
11 │     return new URL(endpoint.trim());
12 │   } catch {
13 │     return undefined;
14 │   }
15 │ }
16 │ 
17 │ /** Drops trailing slashes in one REDACTED (no regular expression: input is user-controlled). */
18 │ function trimTrailingSlashes(text: string): string {
19 │   let end = text.length;
20 │   while (end > 0 && text.charCodeAt(end - 1) === 47) end--;
21 │   return text.slice(0, end);
22 │ }
23 │ 
24 │ /**
25 │  * The best effort for a value that is not a URL: cut at the first `?` or `#`, drop `userinfo@` after `scheme://`.
26 │  * A REDACTEDword may hold a raw `/` (base64), which makes the URL unparseable and moves the `@` out of the authority:
27 │  * when the first segment looks like `user:REDACTEDword` (a colon not followed by a port) the userinfo is cut at the last `@`.
28 │  */
29 │ function stripUnparseable(endpoint: string): string {
30 │   let text = endpoint.trim();
31 │   const cut = [text.indexOf("?"), text.indexOf("#")].filter((i) => i >= 0);
32 │   if (cut.length) text = text.slice(0, Math.min(...cut));
33 │   const schemeEnd = text.indexOf("://");
34 │   if (schemeEnd > 0) {
35 │     const rest = text.slice(schemeEnd + 3);
36 │     const slash = rest.indexOf("/");
37 │     const authority = slash < 0 ? rest : rest.slice(0, slash);
38 │     const looksLikeUserinfo = /^[^@:]*:(?!\d+$)/.test(authority);
39 │     const at = authority.lastIndexOf("@") >= 0 ? authority.lastIndexOf("@") : looksLikeUserinfo ? rest.lastIndexOf("@") : -1;
40 │     if (at >= 0) text = text.slice(0, schemeEnd + 3) + rest.slice(at + 1);
41 │   }
42 │   return trimTrailingSlashes(text);
43 │ }
44 │ 
45 │ /**
46 │  * Origin and path of an endpoint, without userinfo, query or fragment. An unparseable value is cut of those parts as
47 │  * far as it can be; a missing endpoint (a test or partial configuration) stays missing.
48 │  */
49 │ export function persistableEndpoint(endpoint: string): string;
50 │ export function persistableEndpoint(endpoint: string | undefined): string | undefined;
51 │ export function persistableEndpoint(endpoint: string | undefined): string | undefined {
52 │   if (typeof endpoint !== "string") return undefined;
53 │   const url = parse(endpoint);
54 │   if (!url) return stripUnparseable(endpoint);
55 │   return `${url.protocol}//${url.host}${trimTrailingSlashes(url.pathname)}`;
56 │ }
57 │ 
58 │ /** An endpoint URL for equality: scheme and host lower-cased, trailing slashes dropped, no userinfo, query or fragment. */
59 │ export function comparableEndpoint(endpoint: string): string {
60 │   return persistableEndpoint(endpoint);
61 │ }
62 │ 
63 │ /**
64 │  * Free text with credentials cut out of every URL in it: userinfo (to the last `@` before the first `/`, whatever
65 │  * characters the REDACTEDword holds) in `//user:REDACTED@host`, scheme-less `user:REDACTED@host:port/path`, and any scheme URL
66 │  * reduced to `persistableEndpoint` form (no query or fragment). Text without such a shape is returned unchanged.
67 │  */
68 │ export function scrubUrls(text: string): string {
69 │   return text
70 │     .replace(/(\/\/)[^\s\/@:"'<>]+:[^\/\n]*@/g, "$1")
71 │     .replace(/(?<![\w\/@.:-])[^\s\/@:"'<>]+:[^\s\/@"'<>]+@(?=[\w.-]+(?::\d+)?\/)/g, "")
72 │     .replace(/[a-z][a-z0-9+.-]*:\/\/[^\s"'<>]+/gi, (url) => persistableEndpoint(url));
73 │ }
